function searchStocks(query = "", sort = "cap", stocks = DEMO_STOCKS) {
  const q = normalizeSearch(query);
  return stocks.filter((s) => normalizeSearch(s.name).includes(q) || s.id.toLowerCase().startsWith(q)).sort((a, b) => {
    if (sort === "code") return byCode(a, b);
    if (sort === "name") return a.name.localeCompare(b.name, "ko") || byCode(a, b);
    const cap = (s) => Number.isFinite(s.marketCap) ? s.marketCap : -Infinity;
    return cap(b) - cap(a) || 0 || byCode(a, b);
  });
}

// demo/beta-quality-completion/stock-route.mjs
var mapForChange = (change) => Number.isFinite(change) ? change < 0 ? "river" : "lounge" : null;
function stockURL(stock, gender2 = "male") {
  const map = mapForChange(stock?.change);
  if (!map || !stock?.id) return null;
  return `${map}/?${new URLSearchParams(gender2 ? { stock: stock.id, gender: gender2 === "female" ? "female" : "male" } : { stock: stock.id })}`;
}

// demo/beta-quality-completion/stock-entry.mjs
var search = document.querySelector("#choose-stock");
var list = document.querySelector("#stock-list");
var enter = document.querySelector("#stock-enter");
var status = document.querySelector("#selection");
var gender = new URLSearchParams(location.search).get("gender");
var female = document.querySelector('[value="female"]');
if (female && gender === "female") female.checked = true;
var pageSize = 30;
var matches = [];
var chosen = null;
var shown = 0;
function select(stock) {
  chosen = findStock(stock.id);
  search.value = stock.name;
  list.hidden = true;
  const destination = mapForChange(chosen?.change);
  status.textContent = destination ? stock.name + " \u2192 " + (destination === "river" ? "\uD55C\uAC15\uACF5\uC6D0" : "\uB8E8\uD504\uD0D1 \uB77C\uC6B4\uC9C0") : stock.name + " \xB7 \uC2DC\uC138 \uC5F0\uACB0 \uD6C4 \uC785\uC7A5\uD560 \uC218 \uC788\uC5B4\uC694.";
  enter.disabled = !destination;
  if (destination) enter.focus({ preventScroll: true });
  else search.focus({ preventScroll: true });
}
function appendResults() {
  const first = shown;
  const batch = matches.slice(first, first + pageSize);
  for (const stock of batch) {
    const row = document.createElement("button");
    row.type = "button";
    row.className = "stock-row";
    row.dataset.stock = stock.id;
    const name = document.createElement("span");
    name.textContent = stock.name;
    const detail = document.createElement("small");
    detail.textContent = stock.id + (stock.type === "ETF" ? " \xB7 ETF" : " \xB7 " + stock.market);
    name.append(detail);
    row.append(name);
    const demo = findStock(stock.id);
    if (demo) {
      const change = document.createElement("span");
      change.textContent = (demo.change >= 0 ? "+" : "") + demo.change.toFixed(1) + "%";
      change.className = demo.change < 0 ? "down" : "up";
      row.append(change);
    }
    row.onclick = () => select(stock);
    list.append(row);
  }
  shown += batch.length;
  if (shown < matches.length) {
    const more = document.createElement("button");
    more.type = "button";
    more.className = "stock-row";
    more.textContent = "\uACB0\uACFC \uB354 \uBCF4\uAE30";
    more.onclick = () => {
      more.remove();
      appendResults();
    };
    list.append(more);
  }
  if (first > 0) list.children[first].focus();
}
function update() {
  chosen = null;
  enter.disabled = true;
  list.replaceChildren();
  list.scrollTop = 0;
  shown = 0;
  const query = normalizeSearch(search.value);
  matches = query ? searchStocks(query, "name", stock_catalog_default) : [];
  const exact = matches.findIndex((s) => s.id.toLowerCase() === query || normalizeSearch(s.name) === query);
  if (exact > 0) matches.unshift(matches.splice(exact, 1)[0]);
  list.hidden = matches.length === 0;
  status.textContent = query ? matches.length ? "\uAC80\uC0C9 \uACB0\uACFC " + matches.length.toLocaleString("ko-KR") + "\uAC1C" : "\uAC80\uC0C9 \uACB0\uACFC\uAC00 \uC5C6\uC5B4\uC694." : "";
  appendResults();
}
search.addEventListener("input", update);
enter.onclick = () => {
  const url = stockURL(chosen, document.querySelector('[name="gender"]:checked')?.value ?? null);
  if (url) location.assign(url);
};
update();
